  const officialImages={"pps-cf":{"image":"materials/pps-cf.webp","thumbnail":"materials/pps-cf-small.webp","imageWidth":447,"imageHeight":450,"thumbnailWidth":397},"cf-pc":{"image":"materials/cf-pc.webp","thumbnail":"materials/cf-pc-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-etfe":{"image":"materials/cf-etfe.webp","thumbnail":"materials/cf-etfe-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-pa6":{"image":"materials/cf-pa6.webp","thumbnail":"materials/cf-pa6-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-pa66":{"image":"materials/cf-pa66.webp","thumbnail":"materials/cf-pa66-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-pa12":{"image":"materials/cf-pa12.webp","thumbnail":"materials/cf-pa12-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-peek":{"image":"materials/cf-peek.webp","thumbnail":"materials/cf-peek-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-pvdf":{"image":"materials/cf-pvdf.webp","thumbnail":"materials/cf-pvdf-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-pei":{"image":"materials/cf-pei.webp","thumbnail":"materials/cf-pei-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"cf-pfa":{"image":"materials/cf-pfa.webp","thumbnail":"materials/cf-pfa-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400},"long-carbon":{"image":"materials/long-carbon.webp","thumbnail":"materials/long-carbon-small.webp","imageWidth":900,"imageHeight":900,"thumbnailWidth":400}};
