  const applications=[
    {id:'new-energy',name:'新能源',en:'New energy',image:'applications/new-energy.webp',line:'在电气与热环境之间，平衡材料表现。',desc:'围绕电池周边、连接器、充电设备和电机结构件，关注阻燃、绝缘、耐热及尺寸稳定需求。',needs:['明确工作电压、温度与接触介质','结合厚度与测试条件确认阻燃目标','验证绝缘、耐候和实际装配要求'],ids:[],source:base+'new-energy-cases.html'},
    {id:'ai-hardware',name:'AI 与智能硬件',en:'AI & smart hardware',image:'applications/ai-hardware.webp',line:'面向精密结构与静电敏感环境。',desc:'从智能设备外壳到内部支撑与风扇周边部件，将静电控制、热环境、刚性及外观要求放在同一选型框架内。',needs:['明确静电敏感性与电阻目标','关注热环境与长期尺寸表现','结合结构和加工验证纤维取向影响'],ids:["esd-pa-104","esd-pc-104","cf-pa6"],source:base},
    {id:'electronics',name:'消费电子',en:'Consumer electronics',image:'applications/electronics.webp',line:'让外观、结构与使用体验相互配合。',desc:'面向智能设备、家用电器与电子外壳，关注外观一致性、抗冲击、电气需求和精密配合。',needs:['明确颜色、表面与耐候需求','评估卡扣、薄壁及装配结构','结合温升和电气环境验证选型'],ids:["esd-abs-103"],source:base},
    {id:'furniture',name:'办公家具',en:'Office furniture',image:'applications/furniture.webp',line:'从受力结构到长期外观，考虑使用全程。',desc:'围绕扶手、椅背、座托与结构支撑，结合承载方式、疲劳使用、外观及耐候需求展开材料评估。',needs:['明确载荷、冲击与循环使用条件','关注增强材料的刚韧平衡','结合使用环境评估颜色与老化表现'],ids:["cf-pa66"],source:base},
    {id:'medical',name:'医疗设备',en:'Medical devices',image:'applications/medical.webp',line:'材料一致性，从明确条件开始。',desc:'针对医疗设备外壳及精密结构件，关注清洁剂接触、尺寸稳定、可追溯性和项目相关的合规资料。',needs:['明确接触方式与适用法规','结合清洁或消毒方式评估相容性','确认供应批次、资料和验证要求'],ids:["esd-pa-103"],source:base},
    {id:'pet',name:'宠物与生活用品',en:'Pet & everyday products',image:'applications/pet.webp',line:'从日常接触到反复使用，关注材料细节。',desc:'面向智能宠物设备、食品接触部件与结构外壳，结合低气味、韧性、接触条件与长期使用需求进行选型。',needs:['区分食品接触与非接触部位','明确清洗、介质与使用温度','结合硬度、耐磨与外观进行验证'],ids:[],source:base}
  ];
  const articles=[
    {id:'pa6-pa66',category:'selection',title:'PA6 与 PA66，选型先看哪些条件？',intro:'从环境、结构与加工条件出发，理解尼龙材料的选型差异。',image:'material-clear.webp',sections:[['先明确使用条件','对比材料之前，先记录零件的使用温度、受力方式、接触介质、尺寸与外观要求。与其只比较树脂名称，不如把完整工况交给工程团队。'],['把增强与改性一起考虑','同一种基体也可能因增强、增韧、热稳定或阻燃配方而呈现不同表现。PA6、PA66 及其改性体系需要结合具体牌号进行比较。'],['用一致条件验证','阅读资料时，关注测试方法、试样状态和厚度。样品验证还应覆盖真实的装配与使用过程，避免将不同条件下的数据直接比较。']],source:base+'raw-materials.html'},
    {id:'esd-selection',category:'functional',title:'防静电材料，为什么要先明确电阻目标？',intro:'静电控制不是一个单独标签，还需要一致的测试和使用条件。',image:'material-black.webp',sections:[['说清楚静电控制的目的','电子元件保护、灰尘控制与设备干扰，对材料的关注点可能不同。先明确应用目的，再讨论防静电或导电材料。'],['确认测试条件','表面电阻与体积电阻对应不同指标。向供应商提供目标范围、测试方法、温湿度和使用环境，有助于形成可比较的材料建议。'],['同时验证结构表现','静电控制配方还应与冲击、刚性、表面和加工需求一起评估。最终选择需通过具体牌号资料与应用验证。']],source:base+'conductive-materials.html'},
    {id:'flame-insulation',category:'application',title:'阻燃之外，为什么还要关注绝缘性能？',intro:'电气应用中的材料选择，需要把温度、阻燃与绝缘放在一起看。',image:'electronics.webp',sections:[['把要求分开列清楚','阻燃与绝缘对应不同的应用目标。讨论电气材料时，应分别列出项目的阻燃要求、电气条件与热环境，避免用一个指标替代全部需求。'],['结合零件实际状态','试样厚度、结构设计与使用环境会影响验证方案。确认资料中的条件与零件实际状态一致，是开展评估的重要步骤。'],['让验证覆盖真实工况','除了材料资料，还应结合装配、工作电压、湿度、接触介质与长期使用要求制定验证计划。']],source:base+'technical/170.html'},
    {id:'carbon-dimension',category:'application',title:'碳纤增强尼龙：轻量化与尺寸稳定如何兼顾？',intro:'从纤维取向、结构和加工条件出发，关注最终部件的表现。',image:'material-blue.webp',sections:[['从结构目标出发','碳纤维增强体系可用于讨论轻量化和高刚性方案，但材料选择仍需从零件受力、壁厚和连接方式出发。'],['关注加工后的状态','同一材料在不同结构和加工条件下可能产生不同的纤维分布。比较方案时，应关注成型后的实际尺寸及其方向性。'],['以样品评估应用结果','先明确尺寸、刚性与环境要求，再结合试制样品和具体牌号数据进行评估，让材料与结构同步验证。']],source:base+'technical/168.html'},
    {id:'sample-validation',category:'selection',title:'从资料到样品，一份完整的材料验证清单',intro:'先把目标写清楚，再让材料资料与实际应用相互印证。',image:'research.webp',sections:[['资料准备','整理基材、增强或改性方向、颜色、法规以及测试条件。TDS 用于了解材料特性，SDS 用于了解安全信息，批次资料服务于追溯与交付沟通。'],['样品验证','样品试制后，按项目计划核对尺寸、外观与相关性能。记录试制工艺和样品状态，使结果能够被复查。'],['批量沟通','在批量阶段明确关键验收项目、包装与标识、交付计划以及变更沟通方式，让双方对要求形成一致理解。']],source:base+'raw-materials.html'},
    {id:'weathering',category:'functional',title:'耐候与抗黄变：外观之外还要考虑什么？',intro:'将紫外线、热环境和使用周期纳入材料评估。',image:'material-white.webp',sections:[['把环境描述具体','室内光照、户外紫外线、热环境与清洁剂接触，对材料提出的要求并不完全相同。先明确环境与使用周期，再讨论材料方向。'],['同时关注外观与结构','颜色变化只是评价的一部分。耐候材料还应结合项目需要，验证老化前后的力学表现与尺寸状态。'],['确定可执行的验证方案','向工程团队提供目标颜色、使用环境和验收方式，有助于讨论配方、试样与验证计划。']],source:base+'anti-yellowing-aging-parts/'},
    {id:'food-contact',category:'functional',title:'食品接触材料：从使用条件到合规资料',intro:'先明确接触对象与市场，再安排材料与成品验证。',image:'material-ivory.webp',sections:[['明确接触条件','食品种类、温度、接触时长、重复使用与清洗方式，都应纳入项目需求。应根据目标市场确认适用法规与验证方式。'],['资料与成品相互配合','材料资料不能自动替代全部成品验证。颜色、添加体系和加工过程应与项目要求一起确认。'],['保留追溯信息','确认材料批次、供应资料与样品记录，使后续验证、交付和变更沟通有据可查。']],source:base+'food-grade-parts/'},
    {id:'furniture-balance',category:'application',title:'办公家具结构件，如何讨论刚性与韧性？',intro:'从承载、冲击与反复使用的场景出发，梳理材料要求。',image:'architecture.webp',sections:[['把受力方式说清楚','椅背、扶手和座托的承载方式不同，材料讨论应结合部件位置、受力方向与循环使用条件展开。'],['结构与材料一起看','增强体系、壁厚、筋位和装配方式需要共同评估。只看单一力学指标，难以替代完整的结构验证。'],['结合使用全程验证','在试制阶段核对外观、尺寸与相关性能，并根据项目需要补充冲击、疲劳和环境验证。']],source:base}
  ];
  const faqs=[
    ['selection','材料选型需要提供哪些信息？','建议提供使用温度、受力方式、接触介质、尺寸与外观要求、目标法规和预计用量；如有图纸、现有材料或失败样品，也可一并说明。'],
    ['selection','可以定制材料配方吗？','techinherit 官网介绍了材料研发与定制配方能力。可围绕增强、增韧、热稳定、耐候与静电控制等方向沟通，具体方案和开发安排需经工程评估。'],
    ['selection','如何比较 PA6 与 PA66？','先确认工况与结构需求，再比较具体牌号。增强比例、改性配方、含水状态和测试方法均应纳入考虑，避免仅按基体名称作出判断。'],
    ['documents','可以获取 TDS、SDS 或批次资料吗？','请通过材料咨询说明具体牌号和所需文件。TDS、SDS 与批次检验资料的内容和适用范围应分别确认。'],
    ['testing','为什么页面没有统一列出全部性能数值？','材料性能随具体牌号、改性体系、试样状态和测试方法而变化。页面展示材料方向；设计和采购请以确认后的正式资料及验证结果为准。'],
    ['testing','防静电材料如何沟通需求？','请明确表面或体积电阻目标、测试方法、环境以及静电控制目的，同时说明机械、外观和加工要求。'],
    ['testing','食品接触用途需要注意什么？','请说明目标市场、食品类型、接触温度与时长、清洗和重复使用方式，由项目要求确定合适的材料与验证方案。'],
    ['delivery','能否先进行样品验证？','可以先沟通性能目标、所需数量和验证计划。样品、定制开发与交付安排由工程及商务团队依据项目确认。'],
    ['delivery','如何咨询价格与交付时间？','请提供材料方向、预计数量、颜色及定制要求、交付地区和时间目标，以便团队评估报价与排期。']
  ];
